// Open-flow board test (Nexys2-500): the Block Memory wizard's module (#794, bram.v, generated by core/blockram.js from
// table.coe) in Verilog: a ROM of 1500 words of 12 bits (a sine), two RAMB16_S9 side by side. The words are read one
// after the other (all of them about every 1 s), the sine's top 8 bits on the LEDs:
//   LD7-LD0  the sine's bits 11-4, the low four inverted by bits 3-0 (every output bit read: no dangling pin in ISE's DRC)
module top (input clk, output [7:0] led);
  reg [14:0] n = 0;
  reg [10:0] addr = 0;
  wire [11:0] word;
  always @(posedge clk) begin
    n <= n + 1;
    if (n == 0) addr <= addr == 11'd1499 ? 11'd0 : addr + 1;
  end
  bram u_rom (.clka(clk), .addra(addr), .douta(word));
  assign led = word[11:4] ^ {4'b0000, word[3:0]};
endmodule
